インポートするシリアル化されたセッション。 Example WOLFSSL*ssl;
intret;
unsignedcharbuf[MAX];
bufSz=MAX;
...
//getinformationsentfromwc_dtls_exportfunctionandplaceitinbuf
fread(buf,1,bufSz,input);
ret=wolfSSL_dtls_import(ssl,buf,bufSz);
if(ret<0){
//handleerrorcase
}
//nowolfSSL_acceptneededsincehandshakewasalreadydone
...
ret=wolfSSL_write(ssl)andwolfSSL_read(ssl);
...

