メモリの種類 Example WOLFSSL_CTX*ctx;
WOLFSSL*ssl;
intret;
unsignedcharmemory[MAX];
intmemorySz=MAX;
unsignedcharIO[MAX];
intIOSz=MAX;
intflag=WOLFMEM_IO_FIXED|WOLFMEM_TRACK_STATS;
...
//createctxalsousingstaticmemory,startwithgeneralmemorytouse
ctx=NULL:
ret=wolfSSL_CTX_load_static_memory(&ctx,wolfSSLv23_server_method_ex,
memory,memorySz,0,MAX_CONCURRENT_HANDSHAKES);
if(ret!=SSL_SUCCESS){
//handleerrorcase
}
//loadinmemoryforusewithIO
ret=wolfSSL_CTX_load_static_memory(&ctx,NULL,IO,IOSz,flag,
MAX_CONCURRENT_IO);
if(ret!=SSL_SUCCESS){
//handleerrorcase
}
...

