parameterdescription.para:
ピアに送信されるデータバッファ。 Example WOLFSSL*ssl=0;
charmsg[64]=“hellowolfssl!”;
intmsgSz=(int)strlen(msg);
intflags;
intret;
...

ret=wolfSSL_write(ssl,msg,msgSz);
if(ret<=0){
//wolfSSL_write()failed,callwolfSSL_get_error()
}

wolfssl_read（）がデータを読み取るバッファー。 Example WOLFSSL*ssl=0;
charreply[1024];
...

input=wolfSSL_read(ssl,reply,sizeof(reply));
if(input>0){
//“input”numberofbytesreturnedintobuffer“reply”
}

SeewolfSSLexamples(client,server,echoclient,echoserver)formore
completeexamplesofwolfSSL_read().

wolfssl_peek（）がデータを読み取るバッファー。 Example WOLFSSL*ssl=0;
charreply[1024];
...

input=wolfSSL_peek(ssl,reply,sizeof(reply));
if(input>0){
//“input”numberofbytesreturnedintobuffer“reply”
}

simplesect.para:
SSL_FATAL_ERROR エラーが発生した場合は返されます。より詳細なエラーコードを取得するには、wolfssl_get_error（）を呼び出します。 Example intret=0;
interr=0;
WOLFSSL*ssl;
charbuffer[80];
...

ret=wolfSSL_accept(ssl);
if(ret!=SSL_SUCCESS){
err=wolfSSL_get_error(ssl,ret);
printf(“error=%d,%s\n”,err,wolfSSL_ERR_error_string(err,buffer));
}

none 返品不可。 Example WOLFSSL_CTX*ctx=0;
...
wolfSSL_CTX_free(ctx);

none 返品不可。 Example #include<wolfssl/ssl.h>

WOLFSSL*ssl=0;
...
wolfSSL_free(ssl);

SSL_FATAL_ERROR 失敗したときに返されます。より具体的なエラーコードに対してwolfssl_get_error（）を呼び出します。 Example #include<wolfssl/ssl.h>

intret=0;
WOLFSSL*ssl=0;
...
ret=wolfSSL_shutdown(ssl);
if(ret!=0){
//failedtoshutdownSSLconnection
}

parameterdescription.para:
ピアに送信されるデータのサイズ（バイト）。 Example WOLFSSL*ssl=0;
charmsg[64]=“hellowolfssl!”;
intmsgSz=(int)strlen(msg);
intflags=...;
...

input=wolfSSL_send(ssl,msg,msgSz,flags);
if(input!=msgSz){
//wolfSSL_send()failed
}

データを読み込むためのバイト数。 Example WOLFSSL*ssl=0;
charreply[1024];
intflags=...;
...

input=wolfSSL_recv(ssl,reply,sizeof(reply),flags);
if(input>0){
//“input”numberofbytesreturnedintobuffer“reply”
}

