NULL SSLがNULLの場合、SSLセッションキャッシュが無効になっている場合、WolfSSLはセッションIDを使用できない、またはミューテックス関数が失敗します。 Example WOLFSSL*ssl;
WOLFSSL_SESSION*session;
...
session=wolfSSL_get_session(ssl);
if(session==NULL){
//failedtogetsessionpointer
}
...

parameterdescription.para:
wolfssl_ctx_new（）を使用して作成されたwolfssl_ctx構造へのポインタ。 Example WOLFSSL_CTX*ssl;
...
wolfSSL_flush_sessions(ctx,time(0));

セッションIDパラメータの長さを表すint型。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocol);
WOLFSSL*ssl=WOLFSSL_new(ctx);
constbyteid[MAX_SIZE];//ordynamicallycreatespace
intlen=0;//initializelength
intnewSession=0;//flagtoallow
…
intret=wolfSSL_SetServerID(ssl,id,len,newSession);

if(ret==WOLFSSL_SUCCESS){
//TheIdwassuccessfullyset
}

simplesect.para:
int この関数は、wolfssl構造体内のSessionIndexを表すint型を返します。 Example WOLFSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=WOLFSSL_new(ctx);
...
intsesIdx=wolfSSL_GetSessionIndex(ssl);

if(sesIdx<0||sesIdx>sizeof(ssl->sessionIndex)/sizeof(int)){
//Youhaveanoutofboundsindexnumberandsomethingisnotright.
}

parameterdescription.para:
セッションインデックスを表すint型。 Example intidx;//Theindextolocatethesession.
WOLFSSL_SESSION*session;//Buffertocopyto.
...
if(wolfSSL_GetSessionAtIndex(idx,session)!=SSL_SUCCESS){
//Failurecase.
}

simplesect.para:
pointer ピア認証チェーンを含むWOLFSSL_X509_CHAIN構造体へのポインタ。 Example WOLFSSL_SESSION*session;
WOLFSSL_X509_CHAIN*chain;
...
chain=wolfSSL_SESSION_get_peer_chain(session);
if(!chain){
//Therewasnochain.Failurecase.
}

parameterdescription.para:
セッションタイムアウト値（秒） Example WOLFSSL_CTX*ctx=0;
...
wolfSSL_CTX_set_verify(ctx,(WOLFSSL_VERIFY_PEER|
WOLFSSL_VERIFY_FAIL_IF_NO_PEER_CERT),NULL);

セッションタイムアウト値（秒単位）。 Example WOLFSSL*ssl=0;
...
wolfSSL_set_verify(ssl,SSL_VERIFY_PEER|SSL_VERIFY_FAIL_IF_NO_PEER_CERT,0);

wolfssl_new（）を使用して作成されたWolfSSL構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
WOLFSSL*ssl=wolfSSL_new(ctx);
(void*)ctx;
...
if(ssl!=NULL){
wolfSSL_SetCertCbCtx(ssl,ctx);
}else{
//Errorcase,theSSLisnotinitializedproperly.
}

wolfssl_ctx構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
void*userCtx=NULL;//Assignsomeuserdefinedcontext
...
if(ctx!=NULL){
wolfSSL_SetCertCbCtx(ctx,userCtx);
}else{
//Errorcase,theSSLisnotinitializedproperly.
}

