parameterdescription.para:
サーバー名データへのポインタ。 Example intret=0;
WOLFSSL_CTX*ctx=0;
WOLFSSL*ssl=0;
ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}
ssl=wolfSSL_new(ctx);
if(ssl==NULL){
//sslcreationfailed
}
ret=wolfSSL_UseSNI(ssl,WOLFSSL_SNI_HOST_NAME,"www.yassl.com",
strlen("www.yassl.com"));
if(ret!=WOLFSSL_SUCCESS){
//sniusagefailed
}

サーバー名データへのポインタ。 Example intret=0;
WOLFSSL_CTX*ctx=0;
ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}
ret=wolfSSL_CTX_UseSNI(ctx,WOLFSSL_SNI_HOST_NAME,"www.yassl.com",
strlen("www.yassl.com"));
if(ret!=WOLFSSL_SUCCESS){
//sniusagefailed
}

このオプションを設定すると、サーバーはセッションを中止する代わりにSNI応答を送信しません。 Example intret=0;
WOLFSSL_CTX*ctx=0;
WOLFSSL*ssl=0;
ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}
ssl=wolfSSL_new(ctx);
if(ssl==NULL){
//sslcreationfailed
}
ret=wolfSSL_UseSNI(ssl,0,"www.yassl.com",strlen("www.yassl.com"));
if(ret!=WOLFSSL_SUCCESS){
//sniusagefailed
}
wolfSSL_SNI_SetOptions(ssl,WOLFSSL_SNI_HOST_NAME,
WOLFSSL_SNI_CONTINUE_ON_MISMATCH);

このオプションを設定すると、サーバーはセッションを中止する代わりにSNI応答を送信しません。 Example intret=0;
WOLFSSL_CTX*ctx=0;
ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}
ret=wolfSSL_CTX_UseSNI(ctx,0,"www.yassl.com",strlen("www.yassl.com"));
if(ret!=WOLFSSL_SUCCESS){
//sniusagefailed
}
wolfSSL_CTX_SNI_SetOptions(ctx,WOLFSSL_SNI_HOST_NAME,
WOLFSSL_SNI_CONTINUE_ON_MISMATCH);

出力が保存される場所へのポインタ。 Example unsignedcharbuffer[1024]={0};
unsignedcharresult[32]={0};
intlength=32;
//readClientHellotobuffer...
ret=wolfSSL_SNI_GetFromBuffer(buffer,sizeof(buffer),0,result,&length));
if(ret!=WOLFSSL_SUCCESS){
//sniretrievefailed
}

wolfssl_new（）を使用して作成されたWolfSSL構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=wolfSSL_new(ctx);
…
#defineAssertIntEQ(x,y)AssertInt(x,y,==,!=)
…
Bytetype=WOLFSSL_SNI_HOST_NAME;
char*request=(char*)&type;
AssertIntEQ(WOLFSSL_SNI_NO_MATCH,wolfSSL_SNI_Status(ssl,type));
…

どの種類のサーバー名がデータ内で取得されているかを示します。既知の型は次のとおりです。enum {wolfssl_sni_host_name = 0}; Example intret=0;
WOLFSSL_CTX*ctx=0;
WOLFSSL*ssl=0;
ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}
ssl=wolfSSL_new(ctx);
if(ssl==NULL){
//sslcreationfailed
}
ret=wolfSSL_UseSNI(ssl,0,"www.yassl.com",strlen("www.yassl.com"));
if(ret!=WOLFSSL_SUCCESS){
//sniusagefailed
}
if(wolfSSL_accept(ssl)==SSL_SUCCESS){
void*data=NULL;
unsignedshortsize=wolfSSL_SNI_GetRequest(ssl,0,&data);
}

プロトコル名のリストのサイズ。 Example wolfSSL_Init();
WOLFSSL_CTX*ctx;
WOLFSSL*ssl;
WOLFSSL_METHODmethod=//SomewolfSSLmethod
ctx=wolfSSL_CTX_new(method);
ssl=wolfSSL_new(ctx);

charalpn_list[]={};

if(wolfSSL_UseALPN(ssl,alpn_list,sizeof(alpn_list),
WOLFSSL_APN_FAILED_ON_MISMATCH)!=WOLFSSL_SUCCESS)
{
//Errorsettingsessionticket
}

プロトコル名を表すCHARへのポインタは、ALPN構造に保持されます。 Example WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=WOLFSSL_new(ctx);
...
interr;
char*protocol_name=NULL;
Word16protocol_nameSz=0;
err=wolfSSL_ALPN_GetProtocol(ssl,&protocol_name,&protocol_nameSz);

if(err==SSL_SUCCESS){
//SentALPNprotocol
}

バッファへのポインタ。SSLオブジェクトからのデータがコピーされます。 Example #import<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=wolfSSL_new(ctx);
…
#ifdefHAVE_ALPN
char*list=NULL;
word16listSz=0;
…
err=wolfSSL_ALPN_GetPeerProtocol(ssl,&list,&listSz);

if(err==SSL_SUCCESS){
Listofprotocolsnamessentbyclient
}

